public static boolean remove(int val) {
  // Check if the value is in the set
  if (val < 0 || val >= set.length) return false;

  int index = val / width;

  // Check if the value is not already in the set
  if (set[index] == 0) return false;

  // Remap the set elements as necessary
  for (int i = index + 1; i < set.length; i++) {
    // Remove holes in the set
    if (set[i] != 0) {
      set[index] = set[i];
      set[i] = 0;
      index++;
    }
  }

  return true;
}

