    final int asciiValue = ch;
    if (asciiValue > 127) {
        return Character.valueOf(ch);
    } else {
        final Character[] cache = new Character[(127 + 1) + 1];
        for (int i = 0; i < cache.length; i++) {
            cache[i] = Character.valueOf((char) i);
        }
        return cache[asciiValue];
    }
}

