private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
	if (minLabel == 0) {
		throw new IllegalArgumentException("Invalid minLabel");
	}

	Set<Integer> verticesToReload = bucketsByLabel.get(minLabel);
	if (verticesToReload == null || verticesToReload.isEmpty()) {
		return;
	}

	List<Integer> newLabels = new ArrayList<>(verticesToReload.size());
	for (int i = 0; i < verticesToReload.size(); i++) {
		int vertex = verticesToReload.get(i);
		newLabels.add(0);
		labels.set(vertex, 0);
	}

	bucketsByLabel.set(minLabel, null);
	if (bucketsByLabel.size() > minLabel) {
		bucketsByLabel.subList(minLabel, bucketsByLabel.size()).clear();
	}

	bucketsByLabel.addAll(newLabels);
}

