public static int countOccurrencesOf(String str, String sub) {
    if (str == null || sub == null) {
        return 0;
    }
    int count = 0;
    int i = 0;
    int j = 0;
    while (i < str.length()) {
        if (str.charAt(i) == sub.charAt(j)) {
            j++;
            if (j == sub.length()) {
                count++;
                j = 0;
            }
        } else {
            i = i - j;
            j = 0;
        }
        i++;
    }
    return count;
}

