  String time = format.format(c.getTime());

  // Add the timestamp to the message builder
  messageBuilder.append("[" + time + "]");

  // Write the message to each connected client
  for (Socket clientSock : clientSockets) {
    BufferedWriter out = new BufferedWriter(new OutputStreamWriter(clientSock.getOutputStream()));
    out.write(messageBuilder.toString());
    out.flush();
  }
}

