    return 0;
  }
  int numUnusedNodes = 0;
  for (int i = 0; i < categoryTree.size(); i++) {
    CategoryTreeNode node = categoryTree.get(i);
    if (!node.isActive()) {
      numUnusedNodes++;
      categoryTree.remove(node);
    }
  }
  return numUnusedNodes;
}

