public Mappings diffStructure(String tableName, Mappings mappings) {
    // Initialize an empty list to store the diff mappings
    List<FieldMapping> diffMappings = new ArrayList<>();

    // Get the current index mappings
    Mappings currentMappings = getCurrentIndexMappings(tableName);

    // Iterate through the input mappings and check if they exist in the current index mappings
    for (FieldMapping inputMapping : mappings.getMappings()) {
        if (!currentMappings.containsMapping(inputMapping)) {
