static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 1 || dayStep > 31) {
        throw new IllegalArgumentException("Invalid day step: " + dayStep);
    }

    long reFormattedBucket = timeBucket;
    // Convert the time bucket to a string
    String timeBucketStr = Long.toString(timeBucket);

    // Check if the last two digits of the time bucket are greater than or equal to the day step
    if (timeBucketStr.substring(4, 6).toInt() >= dayStep) {
        reFormattedBucket = Long.valueOf(timeBucketStr.substring(0, 4) + dayStep);
    }

    return reFormattedBucket;
}

