public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
    String currentLine;
    String nextLine;
    for(ProfileAnalyzeTimeRange timeRange : timeRanges){
        filteredSnapshots = new ArrayList<>();
        BufferedReader reader = new BufferedReader(new FileReader(file));
        while((currentLine = reader.readLine()) != null) {
            nextLine = reader.readLine();
            if(nextLine != null) {
                if(Math.abs(nextLine -currentLine) <= timeRange.getEnd() && Math.abs(nextLine - currentLine) >= timeRange.getStart()){
                   filteredSnapshots.add(new ThreadSnapshot(nextLine, currentLine));
                }
            }
        }
        threadSnapshots.addAll(filteredSnapshots);
    }
    return threadSnapshots;
}

